BEGIN;
CREATE TYPE application_status AS ENUM ('draft','submitted','identity_review','document_review','academic_review','financial_review','decision_pending','admitted','denied','waitlisted','withdrawn');
CREATE TYPE enrollment_lifecycle AS ENUM ('eligible','offer_accepted','registration_pending','registered','active','leave','withdrawn','completed','conferment_review','conferred');
CREATE TABLE academic_applications(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),tenant_id uuid NOT NULL REFERENCES tenants(id),university_id uuid NOT NULL REFERENCES universities(id),program_version_id uuid REFERENCES program_versions(id),applicant_user_id uuid REFERENCES users(id),status application_status NOT NULL DEFAULT 'draft',entry_term text,application_data jsonb NOT NULL DEFAULT '{}',consent_version text,submitted_at timestamptz,decision_by uuid REFERENCES users(id),decision_at timestamptz,decision_reason text,created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now(),version integer NOT NULL DEFAULT 1);
CREATE TABLE application_requirements(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),tenant_id uuid NOT NULL REFERENCES tenants(id),application_id uuid NOT NULL REFERENCES academic_applications(id) ON DELETE CASCADE,requirement_code text NOT NULL,status text NOT NULL CHECK(status IN ('missing','received','verified','waived','rejected')),evidence_object_key text,verified_by uuid REFERENCES users(id),verified_at timestamptz,UNIQUE(application_id,requirement_code));
CREATE TABLE student_enrollments(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),tenant_id uuid NOT NULL REFERENCES tenants(id),application_id uuid NOT NULL REFERENCES academic_applications(id),student_user_id uuid NOT NULL REFERENCES users(id),program_version_id uuid NOT NULL REFERENCES program_versions(id),status enrollment_lifecycle NOT NULL DEFAULT 'eligible',start_term text,census_status text,sap_status text NOT NULL DEFAULT 'not_evaluated',credits_attempted numeric(6,2) NOT NULL DEFAULT 0,credits_earned numeric(6,2) NOT NULL DEFAULT 0,gpa numeric(4,3),expected_completion date,created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now(),UNIQUE(student_user_id,program_version_id));
CREATE TABLE academic_transmissions(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),tenant_id uuid NOT NULL REFERENCES tenants(id),integration_configuration_id uuid REFERENCES integration_configurations(id),transmission_type text NOT NULL CHECK(transmission_type IN ('enrollment','degree','diploma','fafsa_readiness','state_report','transcript')),batch_reference text NOT NULL,payload_hash text NOT NULL,status text NOT NULL CHECK(status IN ('draft','validation_failed','human_review','approved','sent','acknowledged','rejected','cancelled')),approved_by uuid REFERENCES users(id),approved_at timestamptz,sent_at timestamptz,acknowledgement_reference text,error_summary text,created_at timestamptz NOT NULL DEFAULT now(),UNIQUE(tenant_id,transmission_type,batch_reference),CHECK(status NOT IN ('approved','sent','acknowledged') OR approved_by IS NOT NULL));
CREATE TABLE proctoring_sessions(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),tenant_id uuid NOT NULL REFERENCES tenants(id),assessment_attempt_id uuid NOT NULL REFERENCES assessment_attempts(id),mode text NOT NULL CHECK(mode IN ('practice','live_human','record_review','approved_vendor')),status text NOT NULL CHECK(status IN ('scheduled','identity_pending','ready','in_progress','review','completed','invalidated')),accommodation_plan jsonb NOT NULL DEFAULT '{}',consent_at timestamptz,provider_reference text,flags jsonb NOT NULL DEFAULT '[]',human_reviewer uuid REFERENCES users(id),human_resolution text,created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE conferment_reviews(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),tenant_id uuid NOT NULL REFERENCES tenants(id),student_enrollment_id uuid NOT NULL REFERENCES student_enrollments(id),academic_complete boolean NOT NULL DEFAULT false,financial_clear boolean NOT NULL DEFAULT false,conduct_clear boolean NOT NULL DEFAULT false,authority_clear boolean NOT NULL DEFAULT false,records_verified boolean NOT NULL DEFAULT false,status text NOT NULL CHECK(status IN ('pending','human_review','approved','rejected')),reviewed_by uuid REFERENCES users(id),reviewed_at timestamptz,award_date date,credential_reference text UNIQUE,CHECK(status<>'approved' OR (academic_complete AND financial_clear AND conduct_clear AND authority_clear AND records_verified AND reviewed_by IS NOT NULL)));
CREATE INDEX application_queue ON academic_applications(tenant_id,status,created_at); CREATE INDEX enrollment_progress ON student_enrollments(tenant_id,status,sap_status); CREATE INDEX transmission_queue ON academic_transmissions(tenant_id,status,created_at); CREATE INDEX conferment_queue ON conferment_reviews(tenant_id,status);
ALTER TABLE academic_applications ENABLE ROW LEVEL SECURITY; ALTER TABLE application_requirements ENABLE ROW LEVEL SECURITY; ALTER TABLE student_enrollments ENABLE ROW LEVEL SECURITY; ALTER TABLE academic_transmissions ENABLE ROW LEVEL SECURITY; ALTER TABLE proctoring_sessions ENABLE ROW LEVEL SECURITY; ALTER TABLE conferment_reviews ENABLE ROW LEVEL SECURITY;
CREATE POLICY academic_applications_tenant ON academic_applications USING(tenant_id=current_setting('app.tenant_id',true)::uuid) WITH CHECK(tenant_id=current_setting('app.tenant_id',true)::uuid); CREATE POLICY student_enrollments_tenant ON student_enrollments USING(tenant_id=current_setting('app.tenant_id',true)::uuid) WITH CHECK(tenant_id=current_setting('app.tenant_id',true)::uuid); CREATE POLICY academic_transmissions_tenant ON academic_transmissions USING(tenant_id=current_setting('app.tenant_id',true)::uuid) WITH CHECK(tenant_id=current_setting('app.tenant_id',true)::uuid); CREATE POLICY conferment_reviews_tenant ON conferment_reviews USING(tenant_id=current_setting('app.tenant_id',true)::uuid) WITH CHECK(tenant_id=current_setting('app.tenant_id',true)::uuid);
COMMIT;
